def _eff(df: pd.DataFrame, key: str = "market_id") -> pd.Series:
    """True for units in markets holding >= 2 units of the population (they survive the first-unit drop)."""
    n = df.groupby(key)[key].transform("size")
    return n >= 2


def _vif(df: pd.DataFrame, target: str, others: list[str]) -> float:
    """1 / (1 - R^2) of ``target`` on ``others`` (pooled OLS with intercept, finite rows only)."""
    d = df[[target, *others]].astype(float).replace([np.inf, -np.inf], np.nan).dropna()
    if len(d) < len(others) + 10:
        return float("nan")
    y = d[target].to_numpy()
    X = np.column_stack([np.ones(len(d)), d[others].to_numpy()])
    c, *_ = np.linalg.lstsq(X, y, rcond=None)
    r = y - X @ c
    tss = float(((y - y.mean()) ** 2).sum())
    if tss <= 0:
        return float("nan")
    r2 = 1.0 - float((r**2).sum()) / tss
    return float(1.0 / max(1.0 - r2, 1e-12))


def _ms(v) -> dict:
    v = np.asarray(v, float)
    v = v[np.isfinite(v)]
    if not len(v):
        return {"centre": None, "scale": None, "n": 0}
    return {"centre": float(np.mean(v)), "scale": float(np.std(v, ddof=1)) if len(v) > 1 else None, "n": int(len(v)),
            "terciles": [float(x) for x in np.quantile(v, [1 / 3, 2 / 3])]}


def _day(t) -> np.ndarray:
    return pd.to_datetime(np.asarray(t, float), unit="s", utc=True).strftime("%Y-%m-%d").to_numpy()


def design_effect(ev: pd.Series, scale: float, rho: float) -> dict:
    """Census-computed event design effect (R1 finding 8): m = sum n_e^2 / sum n_e on the census days, projected to 21 days
    as m x scale (pessimistic: every event recurs through the window), DE = 1 + (m_21 - 1) rho."""
    n = ev.value_counts().to_numpy(float)
    m = float((n**2).sum() / n.sum()) if len(n) else float("nan")
    m21 = m * scale
    return {"m_census": m, "m_21d": m21, "rho": rho, "DE": 1.0 + (m21 - 1.0) * rho if np.isfinite(m21) else float("nan")}


def block_anchor(spec: dict, census_days: list[str] | None = None) -> float:
    """UTC-midnight anchor of two-day blocks (R2 finding 10 and re-check finding 2), one rule for census and analysis.
    Analysis (``census_days`` None): REGISTERED_UTC, asserted to be a UTC midnight. Census: the first of that census's own
    UTC days (``YYYY-MM-DD`` or ``YYYYMMDD``), a UTC midnight at an even (zero) offset from itself, so that consecutive
    census days pair into one block (CQ/CH 10-15/10-16 and CF 10-16/10-17 each form one block). Both are even-offset UTC
    midnights: block = floor(day offset / 2) in ``perm_share`` and ``analysis.block_of``."""
    if census_days:
        d = min(str(x).replace("-", "") for x in census_days)
        t = epoch(f"{d[:4]}-{d[4:6]}-{d[6:8]}T00:00:00Z")
    else:
        t = epoch(spec["registered_utc"])
        assert t % 86400.0 == 0.0, "REGISTERED_UTC must be a UTC midnight"
    return t


def de_gate(de: dict, floor: float) -> float:
    """DE used by a census gate: max(floor, computed) (R2 finding 4: rho 0.02 is an example, not an estimate, so the
    computed DE may not loosen R0's 3.0)."""
    return float(max(floor, de["DE"])) if np.isfinite(de["DE"]) else float("nan")


def _family_rule(pop: pd.DataFrame, cap: float) -> tuple[pd.DataFrame, str, float | None]:
    """Answer 9 (R1): if the top series family holds > ``cap`` of the population, it is excluded from the primary."""
    fam = pop["skey"].astype(str).value_counts()
    top = float(fam.iloc[0] / fam.sum()) if len(fam) else None
    if top is not None and top > cap:
        return pop[pop["skey"].astype(str) != fam.index[0]], str(fam.index[0]), top
    return pop, "", top


def _gate(d: dict) -> dict:
    d["pass"] = all(d.values())
    return d


def cleanup_census(work: Path) -> None:
    shutil.rmtree(work, ignore_errors=True)


def demean(df: pd.DataFrame, cols: list[str], group: str, order: str, estimator: str) -> pd.DataFrame:
    X = df[cols].astype(float)
    if estimator == "expanding":
        return bd.expanding_demean(pd.concat([X, df[[group, order]]], axis=1), cols, group, order)[cols]
    if estimator == "fe":
        return X - X.groupby(df[group].to_numpy()).transform("mean")
    return X


def _partial(Z: np.ndarray, v: np.ndarray) -> np.ndarray:
    Z1 = np.column_stack([np.ones(len(v)), Z]) if Z.size else np.ones((len(v), 1))
    c, *_ = np.linalg.lstsq(Z1, v, rcond=None)
    return v - Z1 @ c


def wcorr(df: pd.DataFrame, a: str, c: str) -> dict:
    """Pooled and within-market (expanding-past demeaned, the estimator's own variation) correlations of two columns."""
    d = df[["market_id", "t_row", a, c]].replace([np.inf, -np.inf], np.nan).dropna()
    out = {"pooled": None, "within": None, "n": len(d)}
    if len(d) < 10:
        return out
    if d[a].astype(float).std() > 0 and d[c].astype(float).std() > 0:
        out["pooled"] = float(np.corrcoef(d[a].astype(float), d[c].astype(float))[0, 1])
    X = demean(d, [a, c], "market_id", "t_row", "expanding")
    X = X.replace([np.inf, -np.inf], np.nan).dropna()
    if len(X) >= 10 and X[a].std() > 0 and X[c].std() > 0:
        out["within"] = float(np.corrcoef(X[a], X[c])[0, 1])
    return out


def corr_ok(r: dict, cap: float, both: bool = False) -> bool:
    w, p = r.get("within"), r.get("pooled")
    if w is None or not np.isfinite(w):
        return False
    if both and (p is None or not np.isfinite(p) or abs(p) > cap):
        return False
    return bool(abs(w) <= cap)


def design_ss(df: pd.DataFrame, term: str, controls: list[str]) -> dict:
    """Within-market (expanding-past demeaned) design of ``term`` given ``controls``: the residual sum of squares of the
    demeaned term on the demeaned controls (what governs the coefficient's SE) and the within VIF."""
    cols = [term, *controls]
    d = df[["market_id", "t_row", *cols]].replace([np.inf, -np.inf], np.nan).dropna()
    if len(d) < len(cols) + 10:
        return {"n": len(d), "ss_resid": float("nan"), "vif_w": float("nan")}
    X = demean(d, cols, "market_id", "t_row", "expanding").replace([np.inf, -np.inf], np.nan).dropna()
    Z = X[controls].to_numpy() if controls else np.zeros((len(X), 0))
    xt = _partial(Z, X[term].to_numpy())
    x0 = X[term].to_numpy() - X[term].mean()
    ss, ss0 = float(xt @ xt), float(x0 @ x0)
    return {"n": int(len(X)), "ss_resid": ss, "vif_w": float(ss0 / ss) if ss > 0 else float("inf")}


def mde_class(n1: float, n2: float, sd: float, de: float, a: dict, vif: float = 1.0) -> float:
    """Planning MDE (price units) of a two-class contrast on projected effective counts (section 8 formula)."""
    if not (n1 > 0 and n2 > 0 and np.isfinite(de)):
        return float("inf")
    return a["t_sum"] * sd * math.sqrt(1.0 / n1 + 1.0 / n2) * math.sqrt(de) * a["day_factor"] * math.sqrt(max(vif, 1.0))


def mde_slope_design(ss_resid: float, scale: float, sd: float, de: float, a: dict) -> float:
    """Planning MDE per unit of the (standardised) term from the census design: t_sum x SD / sqrt(projected residual SS)
    x sqrt(DE) x day. Equals section 8's slope formula with the demeaned term's own variance made explicit (section 16)."""
    if not (ss_resid > 0 and np.isfinite(de)):
        return float("inf")
    return a["t_sum"] * sd / math.sqrt(ss_resid * scale) * math.sqrt(de) * a["day_factor"]


def mde_slope_declared(n_eff: float, sd: float, de: float, a: dict, vif: float) -> float:
    """Section 8's slope formula per SD of the term: t_sum x SD / sqrt(n_eff) x sqrt(DE) x day x sqrt(VIF_w)."""
    if not (n_eff > 0 and np.isfinite(de) and np.isfinite(vif)):
        return float("inf")
    return a["t_sum"] * sd / math.sqrt(n_eff) * math.sqrt(de) * a["day_factor"] * math.sqrt(max(vif, 1.0))


def _roots(r) -> list[Path]:
    return [Path(x) for x in (r if isinstance(r, (list, tuple)) else [r])] if r is not None else []


def _scan(work: Path, snapshot_roots, sweep_roots, spec: dict) -> tuple[dict, dict]:
    """Complete captures by slot and sweep 1 by snapshot id over several roots (the host's originals and a restore tree,
    census code check finding 1). Each root is scanned with its own cache; per slot the earliest-starting complete capture
    wins (the vendored rule), per snapshot id the first root that holds a sweep 1."""
    by_slot: dict[int, dict] = {}
    sweeps: dict[str, dict] = {}
    for i, r in enumerate(_roots(snapshot_roots)):
        for k, c in scan_captures(r, State(Path(work) / f"scan_snap{i}"), spec).items():
            if k not in by_slot or c["start"] < by_slot[k]["start"]:
                by_slot[k] = c
    for i, r in enumerate(_roots(sweep_roots)):
        for sid, v in scan_sweeps(r, State(Path(work) / f"scan_sweep{i}")).items():
            sweeps.setdefault(sid, v)
    return by_slot, sweeps


def _name_time(name: str) -> float:
    """Start time from a capture / sweep directory name ``YYYYMMDDTHHMMSSZ_...``; NaN if unparseable."""
    m = re.match(r"^(\d{8})T(\d{6})Z", name)
    if not m:
        return float("nan")
    d, t = m.groups()
    return epoch(f"{d[:4]}-{d[4:6]}-{d[6:]}T{t[:2]}:{t[2:4]}:{t[4:]}Z")


def sealed_dirs(seal: dict, sub: str) -> dict[str, list[str]]:
    """{directory name: [sealed archive paths]} for ``data-dumps/research_lab/<sub>/<dir>/<file>`` entries of a seal."""
    out: dict[str, list[str]] = {}
    pre = f"data-dumps/research_lab/{sub}/"
    for rel in seal.get("files", {}):
        if rel.startswith(pre):
            d = rel[len(pre):].split("/", 1)[0]
            out.setdefault(d, []).append(rel)
    return out


def seal_completeness(seal: dict, by_slot: dict, sweeps: dict, cap_slots: set[int], sweep_slots: set[int], spec: dict,
                      sweep_roots=None) -> dict:
    """Census code check finding 1. (a) Every sealed capture or sweep whose start falls in a needed slot must be present
    locally with every sealed file, else the census is refused ("sealed but absent"). (b) Every opened capture or sweep
    file must itself be sealed with an equal sha256 (``verify_files``). (c) Needed slots with no local capture and no
    sealed capture are genuinely missing: counted, never refused, never imputed."""
    bad: list[dict] = []
    local_caps = {c["id"]: c for c in by_slot.values()}
    allk = sorted(cap_slots | sweep_slots)
    span = (slot_time(allk[0], spec) - 3600.0, slot_time(allk[-1], spec) + 7200.0)

    def slot_for(d: str, rels: list[str]) -> int | None:
        """The seal's own slot assignment (``seal['slots'][dir]``, written by ``seal_captures``) when present, else the
        directory-name time on the grid. A sealed directory inside the needed span that maps to no slot (e.g. a sweep
        starting > 30 min after its slot) refuses the census rather than being left out of the check."""
        if d in seal.get("slots", {}):
            return slot_of(epoch(seal["slots"][d]), spec)
        t = _name_time(d)
        k = slot_of(t, spec) if np.isfinite(t) else None
        if k is None and np.isfinite(t) and span[0] <= t <= span[1]:
            bad.append({"file": rels[0], "error": "sealed directory has no slot assignment (outside the 30-min tolerance)"})
        return k

    for d, rels in sealed_dirs(seal, "snapshots").items():
        k = slot_for(d, rels)
        if k is None or k not in cap_slots:
            continue
        c = local_caps.get(d)
        if c is None:
            bad.append({"file": rels[0], "error": "sealed but absent locally (capture)"})
            continue
        for rel in rels:
            if not (Path(c["dir"]) / rel.rsplit("/", 1)[1]).exists():
                bad.append({"file": rel, "error": "sealed but absent locally"})
    for d, rels in sealed_dirs(seal, "book_sweeps").items():
        k = slot_for(d, rels)
        if k is None or k not in sweep_slots:
            continue
        home = next((Path(r) / d for r in _roots(sweep_roots) if (Path(r) / d).is_dir()), None)
        for rel in rels:
            if home is None or not (home / rel.rsplit("/", 1)[1]).exists():
                bad.append({"file": rel, "error": "sealed but absent locally"})
    files = [f for j in sorted(cap_slots) if j in by_slot for f in capture_files(by_slot[j]["dir"])]
    files += [f for j in sorted(sweep_slots) if j in by_slot and by_slot[j]["id"] in sweeps
              for f in sweep_files(sweeps[by_slot[j]["id"]]["dir"])]
    bad += verify_files(seal, files)
    sealed_slots = {slot_of(epoch(seal["slots"][d]), spec) if d in seal.get("slots", {}) else
                    (slot_of(_name_time(d), spec) if np.isfinite(_name_time(d)) else None) for d in sealed_dirs(seal, "snapshots")}
    missing = sorted(j for j in cap_slots if j not in by_slot and j not in sealed_slots)
    return {"bad": bad, "missing_slots": [iso(slot_time(j, spec)) for j in missing], "n_missing_slots": len(missing),
            "files_checked": len(files)}


def census_slots(days: list[str], spec: dict) -> list[int]:
    """Every grid slot whose slot time falls on one of the UTC ``days`` (present or not)."""
    out = []
    for d in days:
        t0 = epoch(f"{d}T00:00:00Z")
        k0 = slot_of(t0 + 31 * 60, spec)
        out += [k0 + i for i in range(12)]
    return sorted(out)


def shift_plan(codes: np.ndarray, order: np.ndarray, min_n: int) -> list[np.ndarray]:
    """Row indices of each market with >= ``min_n`` rows, sorted by ``order`` (the markets the gate shifts)."""
    out = []
    for c in np.unique(codes):
        idx = np.flatnonzero(codes == c)
        if len(idx) >= min_n:
            out.append(idx[np.argsort(order[idx], kind="mergesort")])
    return out


def offset_range(n: int) -> tuple[int, int]:
    s = max(4, math.ceil(n / 4))
    return s, n - s


def circular_shift(e: np.ndarray, plan: list[np.ndarray], rng: np.random.Generator) -> np.ndarray:
    """One draw: each planned market's residuals rotated by its own uniform offset; other rows unchanged."""
    ep = e.copy()
    for idx in plan:
        lo, hi = offset_range(len(idx))
        ep[idx] = np.roll(e[idx], int(rng.integers(lo, hi + 1)))
    return ep


def block_fl_gate(df: pd.DataFrame, y: np.ndarray, term: str, controls: list[str], *, sign: int, draws: int, seed: int,
                  min_n: int = 16, group: str = "market_id", order: str = "t_row") -> dict:
    """O's gate: as ``fl_perm_gate`` (same demeaning, same reduced-model residuals and statistic), but the null draws
    rotate each market's residual series instead of permuting residuals within strata. p_perm = (1 + #{sign * draw >=
    sign * real}) / (1 + draws) < 0.05 passes."""
    X = demean(df, [term, *controls], group, order, "expanding")
    yv = np.asarray(y, float)
    ok = np.isfinite(yv) & np.all(np.isfinite(X.to_numpy()), axis=1)
    if ok.sum() < 10:
        return {"testable": False, "passes": False, "reason": "fewer than 10 rows"}
    Z = X[controls].to_numpy()[ok] if controls else np.zeros((int(ok.sum()), 0))
    xt = _partial(Z, X[term].to_numpy()[ok])
    e = _partial(Z, yv[ok])
    sxx = float(xt @ xt)
    if sxx <= 1e-18:
        return {"testable": False, "passes": False, "reason": "no residual variation in the term"}
    real = float(xt @ e / sxx)
    codes = pd.factorize(df[group].astype(str).to_numpy()[ok])[0]
    plan = shift_plan(codes, df[order].to_numpy(float)[ok], min_n)
    shifted = int(sum(len(i) for i in plan))
    if not plan:
        return {"testable": False, "passes": False, "reason": f"no market with >= {min_n} rows", "share_rows_shifted": 0.0}
    rng = np.random.default_rng(seed)
    ge = 0
    for _ in range(draws):
        bb = float(xt @ circular_shift(e, plan, rng) / sxx)
        ge += int(sign * bb >= sign * real)
    p = (1 + ge) / (1 + draws)
    return {"testable": True, "real": real, "p_perm": p, "passes": bool(p < 0.05), "draws": draws,
            "method": "block circular-shift Freedman-Lane", "min_n": min_n, "share_rows_shifted": shifted / int(ok.sum()),
            "markets_shifted": len(plan)}


def _norm_cat(v) -> str | None:
    """``strip().casefold()`` of a fee_category; None when absent or null-like."""
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return None
    s = str(v).strip().casefold()
    return None if s in _NULL_LIKE else s


def crypto_class(fee_category, sidecar_present: bool = True, sports: int = 0) -> str:
    """``crypto`` when the sidecar row exists and its fee_category contains ``crypto`` (after strip and casefold); ``non_crypto``
    when it exists, is non-empty and has no ``crypto``; ``unknown`` otherwise (sidecar missing, field absent / empty / null-like, or
    ``sports == -1``). Unknown is counted separately and treated as crypto: every primary keeps only ``non_crypto``."""
    if not sidecar_present or sports == -1:
        return "unknown"
    s = _norm_cat(fee_category)
    if s is None:
        return "unknown"
    return "crypto" if "crypto" in s else "non_crypto"


def crypto_failsafe(values) -> dict:
    """``values``: the distinct ``fee_category`` values (with counts) of the WHOLE sealed sidecar set. If none contains ``crypto``
    (strip, casefold) the classifier is not shown to work and every gate that depends on it is NaN (fails)."""
    cnt: dict[str, int] = {}
    it = values.items() if isinstance(values, dict) else ((v, 1) for v in values)
    for v, n in it:
        key = "" if v is None or (isinstance(v, float) and math.isnan(v)) else str(v)
        cnt[key] = cnt.get(key, 0) + int(n)
    works = any((_norm_cat(v) or "").find("crypto") >= 0 for v in cnt)
    return {"classifier_shown_to_work": bool(works), "distinct_values": dict(sorted(cnt.items())), "gate_value": None if works else float("nan")}


def slot_in_day(k: int) -> int:
    """Index of slot ``k`` within its UTC day on the 2 h grid (grid0 is 00:31Z, so 0 = 00:31Z, 6 = 12:31Z)."""
    return int(k) % 12


class MidStore:
    """Per-slot (mid, spread) of the two-sided quotes, kept as coded arrays (a few hundred KB a slot) so that the 84-slot
    look-back of CH192 and the 3-step paths of CH191 never hold 85 string indexes. Only slots <= the origin are asked for."""

    def __init__(self) -> None:
        self.code: dict[str, int] = {}
        self.slots: dict[int, tuple[np.ndarray, np.ndarray, np.ndarray]] = {}

    def add(self, k: int, ser: pd.DataFrame) -> None:
        ids = ser.index.astype(str)
        codes = np.fromiter((self.code.setdefault(m, len(self.code)) for m in ids), dtype=np.int64, count=len(ids))
        mid = ((ser["bid"].to_numpy(float) + ser["ask"].to_numpy(float)) / 2.0).astype(np.float64)
        self.slots[k] = (codes, mid, ser["spread"].to_numpy(float))

    def matrix(self, k: int, window: int, markets, what: str = "mid") -> np.ndarray:
        """(n_markets, window + 1) of ``mid`` or ``spread`` at slots k - window .. k; NaN where the slot or the market is absent."""
        idx = np.fromiter((self.code.get(str(m), -1) for m in markets), dtype=np.int64, count=len(markets))
        out = np.full((len(idx), window + 1), np.nan)
        ok = idx >= 0
        n = len(self.code)
        for i, j in enumerate(range(k - window, k + 1)):
            if j not in self.slots:
                continue
            codes, mid, spr = self.slots[j]
            arr = np.full(n, np.nan)
            arr[codes] = mid if what == "mid" else spr
            out[ok, i] = arr[idx[ok]]
        return out


def rv_from_matrix(M: np.ndarray, min_obs: int) -> tuple[np.ndarray, np.ndarray]:
    """rms of the consecutive-slot mid changes of the rows of ``M`` (observed = both mids present); NaN below ``min_obs`` changes."""
    d = M[:, 1:] - M[:, :-1]
    obs = np.isfinite(d)
    n = obs.sum(axis=1)
    ss = np.where(obs, d * d, 0.0).sum(axis=1)
    with np.errstate(invalid="ignore", divide="ignore"):
        rv = np.where(n >= min_obs, np.sqrt(ss / np.maximum(n, 1)), np.nan)
    return rv, n


def floored_rv(rv: np.ndarray, tick: np.ndarray, floor_ticks: float) -> tuple[np.ndarray, np.ndarray]:
    """``rv* = max(rv, 0.5 x tick)`` and the flag ``rv_floor = 1[rv < 0.5 x tick]`` (6.B); NaN stays NaN."""
    fl = floor_ticks * np.asarray(tick, float)
    with np.errstate(invalid="ignore"):
        return np.maximum(rv, fl), np.where(np.isfinite(rv) & np.isfinite(fl), (rv < fl).astype(float), np.nan)


def _non_sports_ex_crypto(j: pd.DataFrame, cnt: dict) -> pd.DataFrame:
    """The primaries' category rule: sidecar of k says non-sports (``sports == 0``) and the pinned classifier says non-crypto.
    Unknown (sidecar missing, ``sports == -1``) and crypto are counted and excluded; the sports and crypto arms are reported only."""
    cnt["sports_unknown"] = int((j["sports"] == -1).sum())
    cnt["sports"] = int((j["sports"] == 1).sum())
    j = j[j["sports"] == 0]
    cnt["crypto"] = int((j["crypto7"] == "crypto").sum())
    cnt["crypto_unknown"] = int((j["crypto7"] == "unknown").sum())
    return j[j["crypto7"] == "non_crypto"]


def _hte(end_ts, t_row) -> tuple[np.ndarray, np.ndarray]:
    """log hours-to-end with the declared indicator-pair exception: an unknown end enters as 0 with ``hte_unknown`` (1.5)."""
    hte = (np.asarray(end_ts, float) - np.asarray(t_row, float)) / 3600.0
    unk = ~np.isfinite(hte)
    with np.errstate(invalid="ignore", divide="ignore"):
        lh = np.log(np.clip(hte, 1.0, None))
    return np.where(unk, 0.0, lh), unk.astype(float)


def _own24(sign, mid_k, mid_12) -> tuple[np.ndarray, np.ndarray]:
    """Own 24 h change ``sign x (mid_k - mid_{k-12})`` (sign 1 for unsigned use) with the missing-indicator pair (0 + flag)."""
    d = np.asarray(sign, float) * (np.asarray(mid_k, float) - np.asarray(mid_12, float))
    miss = ~np.isfinite(d)
    return np.where(miss, 0.0, d), miss.astype(float)


def exact_t_sum() -> float:
    """``t_{20, 1 - 0.05/6} + t_{20, 0.8}`` computed exactly (design 1.9: "computed exactly in code")."""
    from scipy import stats

    return float(stats.t.ppf(1.0 - 0.05 / 6.0, 20) + stats.t.ppf(0.8, 20))


def mde_common(spec: dict) -> dict:
    """The spec's ``mde_common`` with ``t_sum = max(declared 3.47, exact)`` (census-code check should-fix: the declared 3.47 is ~0.07% below
    the exact 3.4725..., so the census takes the larger, the pessimistic one)."""
    a = dict(spec["census_gates"]["mde_common"])
    a["t_sum_declared"], a["t_sum_exact"] = a["t_sum"], exact_t_sum()
    a["t_sum"] = max(float(a["t_sum"]), a["t_sum_exact"])
    return a


def block_min_units(covered_days: float, full: int = 16, window: float = 21.0) -> float:
    """``ceil(16 x covered_days / 21)``: the block gate's minimum of 16 shiftable units over 21 days scaled to the census length
    (R1 re-check must-fix 1): 2 for two days, 6 for seven, 3 for 2.75. NaN covered days give +inf (the gate fails)."""
    if not (isinstance(covered_days, (int, float)) and np.isfinite(covered_days) and covered_days > 0):
        return float("inf")
    return float(max(1, math.ceil(full * covered_days / window - 1e-9)))


def block_share(pop: pd.DataFrame, min_units: float) -> float:
    """Share of the population's units in markets holding at least ``min_units`` units of that population (the block-gate
    recurrence proxy). NaN for an empty population."""
    if pop.empty or not np.isfinite(min_units):
        return float("nan")
    n = pop.groupby("market_id")["market_id"].transform("size")
    return float((n >= min_units).mean())


def resid_iqr(pop: pd.DataFrame, y: str, xcols: list[str], min_units: int, iqr_min: float) -> dict:
    """Identification gate of a continuous state (1.0: residual IQR, never the raw IQR): pooled OLS of ``y`` on ``xcols`` (with an
    intercept, finite rows), then each market's IQR of the residual over markets with at least ``min_units`` such rows. Returns
    the share of those markets with IQR >= ``iqr_min`` and their number. The raw IQR is printed beside it, never gated."""
    cols = [y, *xcols]
    d = pop[["market_id", *cols]].copy()
    d[cols] = d[cols].astype(float).replace([np.inf, -np.inf], np.nan)
    d = d.dropna()
    if len(d) < len(cols) + 10:
        return {"share": float("nan"), "markets": 0, "raw_share": float("nan"), "n": len(d)}
    X = np.column_stack([np.ones(len(d)), d[xcols].to_numpy()]) if xcols else np.ones((len(d), 1))
    beta, *_ = np.linalg.lstsq(X, d[y].to_numpy(), rcond=None)
    d["_res"] = d[y].to_numpy() - X @ beta
    g = d.groupby("market_id")
    cnt = g["_res"].transform("size")
    dd = d[cnt >= min_units]
    if dd.empty:
        return {"share": float("nan"), "markets": 0, "raw_share": float("nan"), "n": len(d)}

    def iqr(s: pd.Series) -> float:
        return float(np.quantile(s, 0.75) - np.quantile(s, 0.25))

    ri = dd.groupby("market_id")["_res"].agg(iqr)
    raw = dd.groupby("market_id")[y].agg(iqr)
    return {"share": float((ri >= iqr_min).mean()), "markets": int(len(ri)), "raw_share": float((raw >= iqr_min).mean()), "n": len(d)}


def iqr_ok(r: dict, g: dict) -> bool:
    return bool(np.isfinite(r["share"]) and r["share"] >= g["resid_iqr_share_min"] and r["markets"] >= g["resid_iqr_markets_min"])


def terciles(z) -> tuple[float, float, float]:
    """(lower cut, upper cut, tercile gap = mean of the top tercile minus mean of the bottom tercile) of a standardised state."""
    z = np.asarray(z, float)
    z = z[np.isfinite(z)]
    if len(z) < 3:
        return float("nan"), float("nan"), float("nan")
    t1, t2 = np.quantile(z, [1 / 3, 2 / 3])
    return float(t1), float(t2), float(z[z >= t2].mean() - z[z <= t1].mean())


def standardise(x) -> tuple[float, float]:
    """(centre, scale) = mean and sample SD of the finite values (the census-fixed scale of a state)."""
    x = np.asarray(x, float)
    x = x[np.isfinite(x)]
    if len(x) < 2:
        return float("nan"), float("nan")
    return float(x.mean()), float(x.std(ddof=1))


def _de(pop: pd.DataFrame, scale: float, floor: float, a: dict) -> dict:
    de = design_effect(pop["event_id"].astype(str), scale, float(a["de_rho"]))
    de["DE_gate"] = de_gate(de, float(floor))
    return de


def _gate_min_days(res: dict, key: str, covered_days: float, minimum: float) -> dict:
    """Below its minimum covered days every gate of the census is NaN and fails (design 7)."""
    res["covered_days"], res["min_covered_days"] = covered_days, minimum
    if not (np.isfinite(covered_days) and covered_days >= minimum):
        g = res.get(key, {})
        res[key] = {**{k_: False for k_ in g if k_ != "pass"}, "covered_days": False, "pass": False, "values_nan": True}
    else:
        res[key]["covered_days"] = True
    return res


def _fam(pop: pd.DataFrame, cap: float) -> tuple[pd.DataFrame, str, float | None]:
    return _family_rule(pop, float(cap)) if len(pop) else (pop, "", None)


def _per_market(market_ids: pd.Series) -> dict:
    per = market_ids.astype(str).value_counts()
    dist = per.value_counts().sort_index()
    return {"markets": int(len(per)), "units": int(per.sum()), "units_per_market_hist": {str(int(k_)): int(v) for k_, v in dist.items()},
            "share_in_markets_with_one": float(market_ids.astype(str).map(per).eq(1).mean()) if len(market_ids) else float("nan")}


def _events(pop: pd.DataFrame, scale: float, covered_days: float) -> dict:
    """Events and the projected 21-day events (design 7): ``E_2d + (E_2d - E_day1) x 19`` for a two-day census, else distinct events x
    21 / covered days."""
    if pop.empty:
        return {"events": 0, "events_projected_21d": float("nan"), "covered_days": covered_days}
    ev = pop["event_id"].astype(str)
    days = sorted(pop["day"].astype(str).unique()) if "day" in pop else []
    e_all = int(ev.nunique())
    if len(days) == 2:
        e1 = int(ev[pop["day"].astype(str) == days[0]].nunique())
        return {"events": e_all, "events_day1": e1, "events_projected_21d": float(e_all + (e_all - e1) * 19), "rule": "E_2d + (E_2d - E_day1) x 19", "covered_days": covered_days}
    return {"events": e_all, "events_projected_21d": float(e_all * scale) if np.isfinite(scale) else float("nan"), "rule": "events x 21 / covered days", "covered_days": covered_days}


def unit_overlaps(frames: dict) -> dict:
    """Pairwise overlap of the populations of one census by (market, slot) key (1.11; descriptive, no gate). Cross-census overlaps are not
    computed (each census runs once on its own inputs)."""
    keys = {k_: set(zip(f["market_id"].astype(str), f["slot"], strict=True)) for k_, f in frames.items() if len(f)}
    out = {}
    names = sorted(keys)
    for i, a_ in enumerate(names):
        for b_ in names[i + 1:]:
            n = len(keys[a_] & keys[b_])
            out[f"{a_}&{b_}"] = {"units": n, f"share_of_{a_}": n / len(keys[a_]) if keys[a_] else float("nan"), f"share_of_{b_}": n / len(keys[b_]) if keys[b_] else float("nan")}
    return out


def _z(x, c: float, s: float) -> np.ndarray:
    return (np.asarray(x, float) - c) / s if np.isfinite(s) and s > 0 else np.full(len(x), np.nan)


def _desc_splits(tot: dict) -> dict:
    keys = ("sports", "sports_unknown", "crypto", "crypto_unknown")
    return {k_: int(tot.get(k_, 0)) for k_ in keys}


def _merge_counts(tot: dict, cnt: dict) -> None:
    for a_, v in cnt.items():
        if isinstance(v, dict):
            d = tot.setdefault(a_, {})
            for kk, vv in v.items():
                d[kk] = d.get(kk, 0) + vv
        elif isinstance(v, (int, float, np.integer, np.floating)) and not isinstance(v, bool):
            tot[a_] = tot.get(a_, 0) + v


def _fee_counts(ser: pd.DataFrame, acc: dict) -> None:
    vc = ser["fee_cat"].where(ser["fee_cat"].notna(), None).value_counts(dropna=False)
    for kk, vv in vc.items():
        key = "" if kk is None or (isinstance(kk, float) and np.isnan(kk)) else str(kk)
        acc[key] = acc.get(key, 0) + int(vv)


def load_unavailable(items) -> set[str]:
    """The explicit ``--unavailable`` list (census-code check must-fix 1): archive paths (``data-dumps/research_lab/...``) that q0600's restore
    report says no release holds. Each item is a JSON file (a list of paths, or a restore report whose ``missing`` / ``unavailable`` /
    ``not_found`` list names them) or a plain archive path."""
    out: set[str] = set()
    for it in items or []:
        p = Path(str(it))
        if p.is_file():
            d = json.loads(p.read_text())
            lists = [d] if isinstance(d, list) else [d.get(k_) or [] for k_ in ("missing", "unavailable", "not_found")]
            for lst in lists:
                out |= {str(x["path"] if isinstance(x, dict) else x) for x in lst}
        else:
            out.add(str(it))
    return out


def _utc_day(t: float) -> str:
    return datetime.fromtimestamp(t, UTC).strftime("%Y-%m-%d")


def _status_array(ser: pd.DataFrame) -> np.ndarray:
    """``rew_status`` as strings. pandas reads the cell text ``null`` back from a series CSV as NaN (``read_series`` is a vendored reader and is not edited); a status is never
    legitimately missing, so a NaN status IS ``null``. Without this the carry would never fire on a file read back from the work dir."""
    col = ser["rew_status"]
    return col.where(col.notna(), "null").astype(str).to_numpy()


def _series_ids(ser: pd.DataFrame) -> pd.Index:
    return pd.Index(ser.index.astype(str) if ser.index.name == "market_id" else ser["market_id"].astype(str))


class RewardCarry:
    """Per-slot store of the LISTED ``clob_rewards`` text (market_id -> raw string, with that capture's ``rewards_min_size`` / ``rewards_max_spread``)
    for slots <= the current origin only, kept for the last ``REWARD_CARRY_SLOTS`` slots. ``add(k, ser)`` is called by a census loop for the capture it
    has just read (slots arrive in ascending order); ``apply`` never reads a stored slot later than its ``k`` (a test stores one and asserts it is ignored).
    The null-id sets are held only for the descriptive switching count, never for the primary."""

    def __init__(self, n_slots: int = REWARD_CARRY_SLOTS) -> None:
        self.n = int(n_slots)
        self.slots: dict[int, dict] = {}

    def add(self, k: int, ser: pd.DataFrame) -> None:
        ids = _series_ids(ser)
        st = _status_array(ser)
        lst = st == "listed"
        if "rew_raw" not in ser:
            if lst.any():
                raise ValueError("RewardCarry.add: the series frame has no rew_raw column but has listed rows (a pre-13.7 series file or a reused work dir): refused, never carried silently")
            raw = np.full(len(ids), None, object)
        else:
            raw = ser["rew_raw"].to_numpy(object)
        self.slots[int(k)] = {"listed_ids": pd.Index(ids[lst]), "raw": raw[lst], "rmin": ser["rew_min"].to_numpy(float)[lst], "rms": ser["rew_maxspread"].to_numpy(float)[lst],
                              "null_ids": pd.Index(ids[st == "null"])}
        for old in [s_ for s_ in self.slots if s_ < k - self.n + 1]:
            self.slots.pop(old)

    def apply(self, ser: pd.DataFrame, k: int, day: str) -> pd.DataFrame:
        """A copy of ``ser`` (the frame of slot ``k``) with the 13.7 carry applied to the rows whose ``rew_status`` at ``k`` is ``null``: ``rewarded`` source =
        the LATEST listed capture in slots [k - 11, k - 1] whose text re-parsed for ``day`` (the UTC day of ``k``) gives a rate > 0; ``rew_rate`` / ``rew_min`` /
        ``rew_maxspread`` then come from that source capture. Rows listed, malformed or absent at ``k`` are unchanged. A slot of the window with no stored capture
        is skipped (counted in ``rew_win_missing``), never filled. Adds ``rew_rate_v1`` (the k-only rate), ``rew_carry_lag`` (slots back, NaN if not carried),
        ``rew_param_differs`` (a carried unit whose source min / max-spread differ from the k capture's), ``rew_win_inactive`` (null at k, listed in the window,
        none positive for ``day``), ``rew_trans`` (null/listed transitions of the market over the stored window slots) and ``rew_win_missing``."""
        out = ser.copy()
        ids = _series_ids(out)
        n = len(ids)
        st = _status_array(out)
        out["rew_status"] = st
        rate = out["rew_rate"].to_numpy(float).copy()
        rmin, rms = out["rew_min"].to_numpy(float).copy(), out["rew_maxspread"].to_numpy(float).copy()
        k0_min, k0_ms = rmin.copy(), rms.copy()
        out["rew_rate_v1"] = rate.copy()
        out["rew_min_v1"], out["rew_maxspread_v1"] = k0_min, k0_ms
        lag = np.full(n, np.nan)
        differs = np.zeros(n)
        seen_listed = np.zeros(n, bool)
        todo = np.flatnonzero(st == "null")
        cache: dict[str, float] = {}
        for s in range(int(k) - 1, int(k) - self.n, -1):  # latest first; only slots <= k - 1 (k itself is null for these rows)
            if s not in self.slots or not len(todo):
                continue
            sl = self.slots[s]
            pos = sl["listed_ids"].get_indexer(ids[todo])
            hit = np.flatnonzero(pos >= 0)
            if not len(hit):
                continue
            seen_listed[todo[hit]] = True
            done = []
            for h in hit:
                raw = sl["raw"][pos[h]]
                if not isinstance(raw, str):
                    continue
                r = cache.get(raw)
                if r is None:
                    r = cache[raw] = float(maker_rewards.parse_daily_rate(raw, day))
                if r > 0:
                    i = todo[h]
                    rate[i], rmin[i], rms[i], lag[i] = r, sl["rmin"][pos[h]], sl["rms"][pos[h]], k - s
                    done.append(h)
            if done:
                keep = np.ones(len(todo), bool)
                keep[done] = False
                todo = todo[keep]
        carried = np.isfinite(lag)
        with np.errstate(invalid="ignore"):
            differs = np.where(carried, (~(np.isclose(rmin, k0_min, equal_nan=True))) | (~(np.isclose(rms, k0_ms, equal_nan=True))), False).astype(float)
        present = [s for s in range(int(k) - self.n + 1, int(k) + 1) if s in self.slots and s <= k]
        last = np.full(n, -1, np.int8)
        trans = np.zeros(n)
        for s in present:
            sl = self.slots[s]
            state = np.full(n, -1, np.int8)
            state[sl["null_ids"].get_indexer(ids) >= 0] = 0
            state[sl["listed_ids"].get_indexer(ids) >= 0] = 1
            has = state >= 0
            trans += (has & (last >= 0) & (state != last))
            last = np.where(has, state, last)
        out["rew_rate"], out["rew_min"], out["rew_maxspread"] = rate, rmin, rms
        out["rew_carry_lag"], out["rew_param_differs"] = lag, differs
        out["rew_win_inactive"] = ((st == "null") & seen_listed & ~carried).astype(float)
        out["rew_trans"] = trans
        out["rew_win_missing"] = float(self.n - len(present))
        return out


def _reward_cols(j: pd.DataFrame, cnt: dict) -> tuple[np.ndarray, np.ndarray]:
    """``rew_rate`` and ``rewarded`` (1 if the rate is positive that UTC day, 0 for a null / listed-inactive programme, NaN only for a malformed or absent
    status) of the eligible units, with the status counts. Without the 13.7 carry columns (a frame that never went through :meth:`RewardCarry.apply`) the
    v1 counts of ruling 13.6 apply: ``rewards_null_as_zero`` = every null cell. With them (``listed_carry24h_v2``): ``rewards_null_carried`` (+ ``_lag1``,
    ``_lag2_3``, ``_lag4_11``) = null at k with a listed capture of slots [k - 11, k - 1] whose text re-parsed for day(k) gives a rate > 0 (the unit is
    rewarded, params from the source); ``rewards_null_window_listed_inactive`` = null at k, listed in the window, none positive (unrewarded); ``rewards_null_as_zero``
    = null at k with no listed capture in the window (unrewarded); ``carried_param_differs``; ``reward_switch_markets_1`` / ``_ge2`` = units whose market has
    exactly one / two or more null-listed transitions in the window; ``reward_window_slots_missing`` (once per origin). ``rewards_listed_inactive`` =
    a listed programme with rate 0 at k; ``reward_unparseable`` = malformed ONLY; ``reward_sidecar_absent`` = no sidecar row."""
    st = j["rew_status"].astype(str).to_numpy()
    rew = j["rew_rate"].to_numpy(float)
    cnt["rewards_listed_inactive"] = int(((st == "listed") & np.isfinite(rew) & (rew == 0.0)).sum())
    cnt["reward_unparseable"] = int((st == "malformed").sum())
    cnt["reward_sidecar_absent"] = int((st == "absent").sum())
    if "rew_carry_lag" in j:
        lag = j["rew_carry_lag"].to_numpy(float)
        car = np.isfinite(lag)
        isnull = st == "null"
        cnt["rewards_null_carried"] = int(car.sum())
        cnt["rewards_null_carried_lag1"] = int((car & (lag == 1)).sum())
        cnt["rewards_null_carried_lag2_3"] = int((car & (lag >= 2) & (lag <= 3)).sum())
        cnt["rewards_null_carried_lag4_11"] = int((car & (lag >= 4) & (lag <= 11)).sum())
        inact = j["rew_win_inactive"].to_numpy(float) == 1.0
        cnt["rewards_null_window_listed_inactive"] = int(inact.sum())
        cnt["rewards_null_as_zero"] = int((isnull & ~car & ~inact).sum())
        cnt["carried_param_differs"] = int((j["rew_param_differs"].to_numpy(float) == 1.0).sum())
        tr = j["rew_trans"].to_numpy(float)
        both = np.isin(st, ["null", "listed"])
        cnt["reward_switch_markets_1"] = int((both & (tr == 1)).sum())
        cnt["reward_switch_markets_ge2"] = int((both & (tr >= 2)).sum())
        cnt["reward_window_slots_missing"] = int(j["rew_win_missing"].iloc[0]) if len(j) else 0
    else:
        cnt["rewards_null_as_zero"] = int((st == "null").sum())
    return rew, np.where(np.isfinite(rew), (rew > 0).astype(float), np.nan)


def reward_detail(v, day: str | None = None) -> tuple[float, str, str]:
    """``(daily rate, state, reason)`` of a sidecar ``clob_rewards`` value. An empty / null field is UNREWARDED, not unknown (LT5 R and LT7
    parsed it as NaN and so removed the unrewarded class). States: ``unset`` (None, NaN, empty, whitespace or null-like text; rate 0.0),
    ``empty_list`` (a valid ``[]``; 0.0), ``zero`` (allocations summing to 0 on ``day``), ``rewarded`` (sum > 0) and ``malformed``
    (NON-NULL text that is not a JSON list of dict allocations, or an allocation whose ``rewardsDailyRate`` is non-numeric, boolean,
    negative or not finite; rate NaN: the unit is excluded and counted, never read as 0). ``reason`` (malformed only): ``json`` (does not
    parse), ``not_list``, ``alloc_not_dict`` (an allocation is not an object), ``rate_bad`` (an allocation's rate is unusable)."""
    nan = float("nan")
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return 0.0, "unset", ""
    s = str(v).strip()
    if s.casefold() in _NULL_LIKE:
        return 0.0, "unset", ""
    try:
        arr = json.loads(s)
    except (ValueError, TypeError):
        return nan, "malformed", "json"
    if arr is None:
        return 0.0, "unset", ""
    if not isinstance(arr, list):
        return nan, "malformed", "not_list"
    if not arr:
        return 0.0, "empty_list", ""
    tot = 0.0
    for a in arr:
        if not isinstance(a, dict):
            return nan, "malformed", "alloc_not_dict"
        rate = a.get("rewardsDailyRate")
        if rate is None or (isinstance(rate, str) and rate.strip() == ""):
            r = 0.0
        else:
            if isinstance(rate, bool):
                return nan, "malformed", "rate_bad"
            try:
                r = float(rate)
            except (TypeError, ValueError):
                return nan, "malformed", "rate_bad"
            if not math.isfinite(r) or r < 0:
                return nan, "malformed", "rate_bad"
        if day is not None:
            sd, ed = str(a.get("startDate") or "")[:10], str(a.get("endDate") or "")[:10]
            if (sd and day < sd) or (ed and day > ed):
                continue
        tot += r
    return tot, ("rewarded" if tot > 0 else "zero"), ""


def reward_status(v, day: str | None = None) -> tuple[float, str]:
    """``(daily rate, state)`` of :func:`reward_detail` (see there)."""
    r, s, _ = reward_detail(v, day)
    return r, s


def lt7_status(states) -> np.ndarray:
    return np.array([LT7_STATUS[str(s)] for s in states], dtype=object)


def clob_hash(v) -> str:
    """Short stable hash of the normalised ``clob_rewards`` string (null / empty / null-like all normalise to the empty string)."""
    if v is None or (isinstance(v, float) and math.isnan(v)) or str(v).strip().casefold() in _NULL_LIKE:
        return ""
    return hashlib.blake2b(str(v).strip().encode("utf-8"), digest_size=8).hexdigest()


def rw_frame(ext: pd.DataFrame | None, day: str) -> pd.DataFrame:
    """One row per SIDECAR row of a capture (not only the two-sided markets of the series file): the ``clob_rewards`` hash (``rw_changed``), the 13.7 status
    in the LT7 vocabulary, the raw text of a LISTED cell only (the carry source; None otherwise) and that capture's ``rewards_min_size`` /
    ``rewards_max_spread``. 13.7 erratum: a sidecar WITHOUT the ``clob_rewards`` column has ``clob_h`` NaN (never the empty-programme hash ``""``), so
    ``rw_changed`` is NaN when capture k or k - 2 is ``no_column`` (check fix 7); :func:`read_rw8` restores the NaN after the CSV round trip."""
    if ext is None:
        return pd.DataFrame({c: [] for c in RW_COLS})
    has_col = bool(ext.attrs.get("has_clob_rewards", True))
    vals = ext["clob_rewards"].tolist()
    st = lt7_status([reward_detail(v, day)[1] if has_col else "no_column" for v in vals])
    raw = [v if s == "listed" else None for v, s in zip(vals, st, strict=True)]
    h = [clob_hash(v) if s != "no_column" else None for v, s in zip(vals, st, strict=True)]
    return pd.DataFrame({"market_id": ext.index.astype(str), "clob_h": pd.Series(h, dtype=object).to_numpy(), "rew_status": st, "rew_raw": pd.Series(raw, dtype=object).to_numpy(),
                         "rew_min": pd.to_numeric(ext["rewards_min_size"], errors="coerce").to_numpy(float), "rew_maxspread": pd.to_numeric(ext["rewards_max_spread"], errors="coerce").to_numpy(float)})


def read_rw8(work: Path, cap_id: str | None) -> pd.DataFrame | None:
    """The :func:`rw_frame` of a capture read back, indexed by market_id (no NA parsing of the text columns: ``null`` stays ``null``; an empty
    ``rew_raw`` is None; a ``no_column`` row's ``clob_h`` is NaN, 13.7 erratum). An rw file without the 13.7 columns (an older work dir) is refused, never
    read as unrewarded."""
    if cap_id is None:
        return None
    p = Path(work) / "rw" / f"{cap_id}.csv.gz"
    if not p.exists():
        return None
    d = pd.read_csv(p, dtype=str, keep_default_na=False)
    if not set(RW_COLS) <= set(d.columns):
        raise ValueError(f"rw file {p.name} lacks the 13.7 columns {sorted(set(RW_COLS) - set(d.columns))}: refused (a pre-13.7 work dir)")
    d = d.drop_duplicates("market_id").set_index("market_id")
    d["rew_raw"] = d["rew_raw"].where(d["rew_raw"] != "", None)
    d["clob_h"] = d["clob_h"].where(d["rew_status"] != "no_column", np.nan)  # 13.7 erratum: an absent column is not an empty programme
    for c in ("rew_min", "rew_maxspread"):
        d[c] = pd.to_numeric(d[c], errors="coerce")
    return d


def _vol_cols(vol24) -> tuple[np.ndarray, np.ndarray]:
    """``log1p volume24hr`` with the declared indicator pair (1.5): a missing value enters as 0 with ``vol_missing``."""
    v = np.asarray(vol24, float)
    miss = ~np.isfinite(v)
    return np.where(miss, 0.0, np.log1p(np.clip(np.where(miss, 0.0, v), 0, None))), miss.astype(float)


